package identity

import (
	"context"
	"crypto/rand"
	"crypto/subtle"
	"database/sql"
	"encoding/base64"
	"errors"
	"fmt"
	"strings"

	"golang.org/x/crypto/argon2"
)

// Password hashing is argon2id with PINNED parameters (accounts design.md
// D6: the ONE password hashing in the repo — device tokens stay SHA-256).
// t=1, m=64MiB, p=1: the memory-hard floor a TV-class box can afford once
// per login. Parameters are pinned, not negotiated — a stored PHC string
// that carries other parameters still verifies against ITS OWN header (the
// decode reads them back), but hashPassword always writes the pinned set.
const (
	argonTime    = 1
	argonMemory  = 64 * 1024 // KiB — 64 MiB
	argonThreads = 1
	argonKeyLen  = 32
	argonSaltLen = 16
)

// phcParams is the pinned parameter set, pre-rendered for the encoder.
const phcParams = "m=65536,t=1,p=1"

// b64 is the PHC standard encoding without padding (the argon2 reference).
var b64 = base64.RawStdEncoding

// hashPassword hashes password argon2id into the PHC string form:
// $argon2id$v=19$m=65536,t=1,p=1$<salt>$<hash>.
func hashPassword(password string) (string, error) {
	salt := make([]byte, argonSaltLen)
	if _, err := rand.Read(salt); err != nil {
		return "", fmt.Errorf("identity: salt: %w", err)
	}
	key := argon2.IDKey([]byte(password), salt, argonTime, argonMemory, argonThreads, argonKeyLen)
	return "$argon2id$v=19$" + phcParams + "$" + b64.EncodeToString(salt) + "$" + b64.EncodeToString(key), nil
}

// verifyPassword checks password against a stored PHC hash: the stored
// string's own header supplies the parameters (a hash written by an older
// parameter set still verifies), and the comparison is constant-time.
func verifyPassword(password, phc string) (bool, error) {
	fields := strings.Split(phc, "$")
	// "": "argon2id": "v=19": "m=…,t=…,p=…": salt: hash — 6 fields.
	if len(fields) != 6 || fields[1] != "argon2id" || fields[2] != "v=19" {
		return false, fmt.Errorf("identity: malformed password hash")
	}
	var (
		memory, timeParam uint32
		threads           uint8
	)
	if _, err := fmt.Sscanf(fields[3], "m=%d,t=%d,p=%d", &memory, &timeParam, &threads); err != nil {
		return false, fmt.Errorf("identity: hash params: %w", err)
	}
	salt, err := b64.DecodeString(fields[4])
	if err != nil {
		return false, fmt.Errorf("identity: hash salt: %w", err)
	}
	want, err := b64.DecodeString(fields[5])
	if err != nil {
		return false, fmt.Errorf("identity: hash key: %w", err)
	}
	got := argon2.IDKey([]byte(password), salt, timeParam, memory, threads, uint32(len(want)))
	return subtle.ConstantTimeCompare(got, want) == 1, nil
}

// VerifyPassword checks a credential: (true, nil) means the password
// matches. Unknown user and wrong password BOTH return (false, nil) — no
// existence signal escapes this method, so mint (3.3) folds every failure
// into one uniform auth-failure posture (D6: no account enumeration). The
// disabled gate is the caller's refusal (mint), not a credential fact.
func (s *Service) VerifyPassword(ctx context.Context, username, password string) (bool, error) {
	name, err := normalizeUsername(username)
	if err != nil {
		return false, err
	}
	var hash string
	err = s.st.DB().QueryRowContext(ctx,
		`SELECT password_hash FROM users WHERE username = ?`, name).Scan(&hash)
	if errors.Is(err, sql.ErrNoRows) {
		return false, nil
	}
	if err != nil {
		return false, fmt.Errorf("identity: verify password: %w", err)
	}
	return verifyPassword(password, hash)
}

// ResetPassword rehashes the credential and persists it, and auto-revokes
// every session credential of the user (D6: a password change kills its
// sessions) — the rehash and the session cascade run in ONE transaction, so
// a reset never leaves a live session on a stale credential. Device rows
// are untouched: the cascade deletes kind='session' only. Unknown users
// surface as the wrapped sql.ErrNoRows unknown-user convention (the
// execOne posture this tx replaces).
func (s *Service) ResetPassword(ctx context.Context, username, password string) error {
	name, err := normalizeUsername(username)
	if err != nil {
		return err
	}
	hash, err := hashPassword(password)
	if err != nil {
		return err
	}
	tx, err := s.st.DB().BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("identity: reset password tx: %w", err)
	}
	defer func() { _ = tx.Rollback() }()
	res, err := tx.ExecContext(ctx,
		`UPDATE users SET password_hash = ?, updated_at = ? WHERE username = ?`,
		hash, formatStamp(s.now()), name)
	if err != nil {
		return fmt.Errorf("identity: reset password: %w", err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return fmt.Errorf("identity: reset password affected: %w", err)
	}
	if n == 0 {
		return fmt.Errorf("identity: reset password: unknown user: %w", sql.ErrNoRows)
	}
	if _, err = tx.ExecContext(ctx,
		`DELETE FROM credentials WHERE kind = 'session'
AND user_id = (SELECT id FROM users WHERE username = ?)`, name); err != nil {
		return fmt.Errorf("identity: reset password session cascade: %w", err)
	}
	return tx.Commit()
}
